// Package turbocassette will record and replay VCR cassettes against go http Handlers.
package turbocassette

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"net/http/httptest"
	"net/textproto"
	"net/url"
	"os"
	"runtime"
	"strconv"
	"strings"
	"time"

	"github.com/github/turbocassette/vcr"

	"github.com/jpillora/longestcommon"

	"github.com/pkg/errors"
	"github.com/pmezard/go-difflib/difflib"
)

// CassetteChanged can be used to check if an error is due to cassettes being different to the representation on disk:
// if errors.Is(err, turbocassette.CassetteChanged) {
var CassetteChanged CassetteChangedError

type CassetteChangedError string

func (e CassetteChangedError) Error() string {
	return string(e)
}

func (e CassetteChangedError) Is(err error) bool {
	var out CassetteChangedError
	return errors.As(err, &out)
}

// replay runs VCR and updates the responses, if they are different
func replay(ctx context.Context, p *Player, tape *vcr.Cassette) error {
	now := time.Now()

	for _, interaction := range tape.Interactions {
		requestURI, err := url.Parse(interaction.Request.URI)
		if err != nil {
			return err
		}

		// skip any request that was not meant for this host
		if p.host != nil && (requestURI.Host != *p.host) {
			continue
		}

		recorder := httptest.NewRecorder()

		request := &http.Request{
			Method: strings.ToUpper(interaction.Request.Method),
			URL:    requestURI,
			Body:   ioutil.NopCloser(strings.NewReader(interaction.Request.Body.String)),
			Header: interaction.Request.Headers,
		}
		request = request.WithContext(ctx)

		p.handler.ServeHTTP(recorder, request)

		response := recorder.Result()

		if interaction.Response != nil && interaction.Response.Status != nil && interaction.Response.Status.Code != response.StatusCode {
			body, _ := ioutil.ReadAll(response.Body)
			_ = response.Body.Close()
			return errors.Errorf(
				"response for %v does not match recording: expected(%d) != actual(%d)\n\t%s",
				requestURI.Path,
				interaction.Response.Status.Code,
				response.StatusCode,
				string(body),
			)
		}

		// we do not need the response body, however it must be closed to avoid resource leaks
		_ = response.Body.Close()

		body := recorder.Body.String()
		for _, filter := range p.rawResponseFilter {
			body = filter(body)
		}

		if response.Header.Get("Content-Type") == "application/json" {
			// protobuf randomly inserts spaces and you cannot reliably compare json strings
			// re-encode using the standard library
			body = normalizeJson(body)
		}

		response.Header.Set("Content-Length", strconv.Itoa(len(body)))

		recording := &vcr.Response{
			Status: &vcr.Status{
				Code: recorder.Code,
			},
			Body: &vcr.Body{
				Encoding: "UTF-8",
				String:   body,
			},
			Headers: response.Header,
		}

		if interaction.RecordedAt != "" {
			// check that the recorded at is valid
			_, err = time.Parse(http.TimeFormat, interaction.RecordedAt)
			if err != nil {
				return err
			}
		}

		// Normalize request headers and remove non-informative ones
		for key, value := range request.Header {
			delete(request.Header, key)
			normalizedKey := textproto.CanonicalMIMEHeaderKey(key)
			if _, ok := p.ignoreRequestHeaders[normalizedKey]; ok {
				continue
			}
			request.Header[normalizedKey] = value
		}

		// Normalize request body for readability
		if request.Header.Get("Content-Type") == "application/json" {
			interaction.Request.Body.String = normalizeJson(interaction.Request.Body.String)
		}

		// reduce the noise in diffs by only updating the timestamp of things
		// that have changed
		if vcr.IsResponseModified(interaction.Response, recording) {
			interaction.Response = recording
			interaction.RecordedAt = now.UTC().Format(http.TimeFormat)
		}
	}

	return nil
}

func normalizeJson(input string) string {
	var decoded interface{}
	if err := json.Unmarshal([]byte(input), &decoded); err == nil {
		if encoded, err := json.MarshalIndent(&decoded, "", "  "); err == nil {
			return string(encoded)
		}
	}
	return input
}

// overwriteTape loads the cassette at name and then replaces it after any modifications have been performed
// by the replay method.
func overwriteTape(ctx context.Context, fd *os.File, replayFn func(context.Context, *vcr.Cassette) error) error {
	name := fd.Name()
	// create a separate file and atomically move it into place
	// leave the file if anything goes wrong so that the user can inspect the result
	tmp, err := os.Create(name + ".tmp")
	if err != nil {
		return err
	}
	defer tmp.Close()

	// signpost how this cassette was updated with a callback to the file that called Record
	_, file, _, _ := runtime.Caller(3)
	prefix := longestcommon.Prefix([]string{file, name})
	_, err = fmt.Fprintf(tmp, "# generated by turbocassette %s\n---\n", strings.TrimPrefix(file, prefix))
	if err != nil {
		return err
	}

	tape, err := vcr.Open(fd)
	if err != nil {
		return err
	}

	err = replayFn(ctx, tape)
	if err != nil {
		return err
	}

	err = tape.Encode(tmp)
	if err != nil {
		return err
	}

	err = tmp.Close()
	if err != nil {
		return err
	}

	return os.Rename(tmp.Name(), fd.Name())
}

// diffTape loads the tape and returns an error if it was modified by replay
func diffTape(ctx context.Context, tape *vcr.Cassette, replayFn func(context.Context, *vcr.Cassette) error) error {
	var before bytes.Buffer
	var after bytes.Buffer

	// re-encode to ignore comments or any formatting differences
	err := tape.Encode(&before)
	if err != nil {
		return err
	}

	err = replayFn(ctx, tape)
	if err != nil {
		return err
	}

	err = tape.Encode(&after)
	if err != nil {
		return err
	}

	diff := difflib.UnifiedDiff{
		A:        difflib.SplitLines(before.String()),
		B:        difflib.SplitLines(after.String()),
		FromFile: "Original",
		FromDate: "",
		ToFile:   "Current",
		ToDate:   "",
		Context:  2,
	}
	text, err := difflib.GetUnifiedDiffString(diff)
	if err != nil {
		return err
	}
	if text != "" {
		return CassetteChangedError(text)
	}
	return nil
}
